python3 -c 'import sys,shlex,json;s='"'"'import sys,shlex,json;s=@;q=s.replace("@",repr(s),1);C="python3 -c "+shlex.quote(q)+" "+chr(34)+"$@"+chr(34);exec(\'p=[];j=2\\nwhile len(p)<256:\\n if all(j%d for d in p if d*d<=j):p.append(j)\\n j+=1\\nv={x:i for i,x in enumerate(p)}\\ndef E(b):\\n n=1\\n for x in b:n=2048*n+p[x]\\n return n\\ndef D(n):\\n if n<1:raise ValueError("G")\\n b=[]\\n while n>1:\\n  n,r=divmod(n,2048)\\n  if r not in v:raise ValueError("atom")\\n  b.append(v[r])\\n return bytes(b[::-1])\\na=sys.argv[1:]\\nif a[:1]==["-e"]:assert len(a)==3;print(hex(E(json.dumps(a[1:3],ensure_ascii=False,separators=(",",":" )).encode())))\\nelif a[:1]==["-d"]:print(D(int(a[1],0)).decode())\\nelif a==["-g"]:print(1)\\nelif a==["-G"]:print(hex(E(C.encode())))\\nelif a==["-v"]:\\n assert D(E(C.encode()))==C.encode()\\n assert all((""+x==x+""==x) for x in ("","abc",chr(127756)))\\n print("G=1;identity=True;roundtrip=True")\\nelif a==["-p"]:print("G=empty word; Gx=x=xG; a,b identities => a=ab=b; homomorphisms preserve G")\\nelse:print(C)\'"'"')'"'"';q=s.replace("@",repr(s),1);C="python3 -c "+shlex.quote(q)+" "+chr(34)+"$@"+chr(34);exec('"'"'p=[];j=2\nwhile len(p)<256:\n if all(j%d for d in p if d*d<=j):p.append(j)\n j+=1\nv={x:i for i,x in enumerate(p)}\ndef E(b):\n n=1\n for x in b:n=2048*n+p[x]\n return n\ndef D(n):\n if n<1:raise ValueError("G")\n b=[]\n while n>1:\n  n,r=divmod(n,2048)\n  if r not in v:raise ValueError("atom")\n  b.append(v[r])\n return bytes(b[::-1])\na=sys.argv[1:]\nif a[:1]==["-e"]:assert len(a)==3;print(hex(E(json.dumps(a[1:3],ensure_ascii=False,separators=(",",":" )).encode())))\nelif a[:1]==["-d"]:print(D(int(a[1],0)).decode())\nelif a==["-g"]:print(1)\nelif a==["-G"]:print(hex(E(C.encode())))\nelif a==["-v"]:\n assert D(E(C.encode()))==C.encode()\n assert all((""+x==x+""==x) for x in ("","abc",chr(127756)))\n print("G=1;identity=True;roundtrip=True")\nelif a==["-p"]:print("G=empty word; Gx=x=xG; a,b identities => a=ab=b; homomorphisms preserv